import { IFuncOrigin, IFuncOperatorOrigin, IFuncOperator } from '@/interface/IFunc';
import { Script } from '@/system/script';
// const normal = -1; //定义常量
const left = 0;
const center = 1;
const right = 2;

export class Func693 implements IFuncOrigin {
	id = 693;
	name = '师傅流程';
	config = [{
		desc: '',
		config: [{
			name: 'name',
			desc: '徒弟昵称关键字',
			type: 'text',
			default: '徒弟',
